    const scale = 230 / 520;
    const x = 205;
    const points = [[1467, 1932], [1499, 1952], [1505, 1966], [1538, 2009], [1494, 2018], [1453, 2000], [1433, 1977], [1430, 1970]];
    const marks = points.map(([px, py]) => y2025Dot(x + scale * (px - 1103), 1 + scale * (py - 1702), 2.6, y2025Orange)).join('');
